from typing import List, Tuple

def f(inputs: List[Tuple[int, List[Tuple[str, int, int, int]]]]) -> str:
    result = []
    for n, teams in inputs:
        team_scores = []
        for name, w, l, d in teams:
            team_score = 0
            if w > l:
                team_score += 3
            elif w == l:
                team_score += 1
            if d == 0:
                team_score -= 1
            team_scores.append((name, team_score))
        team_scores.sort(key=lambda x: (-x[1], x[0]))
        result.append('\n'.join([f"{name} {score}" for name, score in team_scores]))
    return '\n'.join(result)
